tool.schemaJson:
{
  "type": "object",
  "properties": {
    "dashboardName": {
      "type": "string",
      "description": "Name of the dashboard to create."
    },
    "description": {
      "type": "string",
      "description": "Optional description of the dashboard."
    },
    "panels": {
      "type": "array",
      "description": "Panels to create within the dashboard. Only the 8 dashboard component types are allowed: chart, table, stat-tile, text, container, pivot-table, map, iframe. Decorative/media types (decorative-border, scroll-text, time-clock, video, stream, carousel-tab) are reserved for screens and will be rejected.",
      "items": {
        "type": "object",
        "properties": {
          "title": {
            "type": "string",
            "description": "Panel title (mapped to panelName)."
          },
          "componentType": {
            "type": "string",
            "description": "One of the 8 dashboard component types: chart, table, stat-tile, text, container, pivot-table, map, iframe. Components that need data (chart/table/stat-tile/map/pivot-table) require datasetSid; text/iframe/container do not."
          },
          "datasetSid": {
            "type": "string",
            "description": "The dataset ID (sid) to bind this panel to. Required for chart/table/stat-tile/map/pivot-table (needsDataset=true). Omit for text/iframe/container. The dataset MUST be active (status=1) AND visible to the current user (created by the current user, or you are acting as admin); a non-existent/inactive dataset returns ERR_DATAV_CHATBI_GENERATE_DATASET_NOT_FOUND, an existing active dataset that is NOT visible to the current user returns ERR_DATAV_CHATBI_DATASET_NO_ACCESS. Multiple panels referencing the same datasetSid share one DatasetRef (deduplicated within the dashboard)."
          },
          "fieldMapping": {
            "type": "object",
            "description": "Optional field mapping config stored in panelConfig.fieldMapping for front-end rendering. Each referenced field name must exist in the dataset's dsMeta field set. Example: {\"x\":\"region\",\"y\":\"amount\"}.",
            "additionalProperties": true
          },
          "sortOrder": {
            "type": "integer",
            "description": "Optional sort order. If omitted, panels are ordered by declaration order (0,1,2,...)."
          }
        },
        "required": ["title", "componentType"]
      }
    }
  },
  "required": ["dashboardName", "panels"]
}
